class UndergroundSystem {
    unordered_map<int, pair<string, int>> checkIns;
    unordered_map<string, pair<long long, int>> travelTimes;

    string getKey(const string& s1, const string& s2) {
        return s1 + "," + s2;
    }
public:
    UndergroundSystem() {

    }

    void checkIn(int id, string stationName, int t) {
        checkIns[id] = {stationName, t};
    }

    void checkOut(int id, string stationName, int t) {
        auto it = checkIns.find(id);
        string startStation = it->second.first;
        int checkInTime = it->second.second;
        string key = getKey(startStation, stationName);
        travelTimes[key].first += (long long)(t - checkInTime);
        travelTimes[key].second++;
        checkIns.erase(id);
    }

    double getAverageTime(string startStation, string endStation) {
        string key = getKey(startStation, endStation);
        auto& entry = travelTimes[key];
        return (double)entry.first / entry.second;
    }
};
